-- PostgreSQL 15+; synthetic survey metadata only, no respondent-level PII.
CREATE SCHEMA IF NOT EXISTS ubos_demo;
CREATE TABLE IF NOT EXISTS ubos_demo.survey_programmes(programme_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,programme_code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,domain TEXT NOT NULL CHECK(domain IN('agriculture','labour','prices','health','education','business','other')),owner_ref TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('draft','active','paused','closed')));
CREATE TABLE IF NOT EXISTS ubos_demo.survey_waves(wave_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,wave_ref TEXT NOT NULL UNIQUE,programme_id BIGINT NOT NULL REFERENCES ubos_demo.survey_programmes(programme_id) ON DELETE RESTRICT,reference_period_start DATE NOT NULL,reference_period_end DATE NOT NULL,fieldwork_start DATE,fieldwork_end DATE,status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN('planned','fieldwork','processing','quality_review','complete','cancelled')),CHECK(reference_period_end>=reference_period_start),CHECK(fieldwork_end IS NULL OR fieldwork_start IS NULL OR fieldwork_end>=fieldwork_start));
CREATE TABLE IF NOT EXISTS ubos_demo.instruments(instrument_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,instrument_code TEXT NOT NULL,version_no INTEGER NOT NULL CHECK(version_no>0),title TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','approved','retired')),approved_at TIMESTAMPTZ,UNIQUE(instrument_code,version_no),CHECK(status<>'approved' OR approved_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS ubos_demo.sample_units(sample_unit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,wave_id BIGINT NOT NULL REFERENCES ubos_demo.survey_waves(wave_id) ON DELETE RESTRICT,sample_token TEXT NOT NULL,area_code TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('interview','administrative_source','observation','other')),response_status TEXT NOT NULL DEFAULT 'pending' CHECK(response_status IN('pending','complete','partial','nonresponse','invalidated')),quality_state TEXT NOT NULL DEFAULT 'unreviewed' CHECK(quality_state IN('unreviewed','passed','flagged','resolved')),UNIQUE(wave_id,sample_token));
CREATE TABLE IF NOT EXISTS ubos_demo.aggregate_cells(cell_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,wave_id BIGINT NOT NULL REFERENCES ubos_demo.survey_waves(wave_id) ON DELETE RESTRICT,table_ref TEXT NOT NULL,area_code TEXT NOT NULL,metric_code TEXT NOT NULL,cell_count INTEGER NOT NULL CHECK(cell_count>=0),value NUMERIC(20,4),suppression_state TEXT NOT NULL DEFAULT 'pending' CHECK(suppression_state IN('pending','publishable','suppressed','withheld')),UNIQUE(wave_id,table_ref,area_code,metric_code),CHECK(suppression_state<>'publishable' OR cell_count>=10));
CREATE TABLE IF NOT EXISTS ubos_demo.release_events(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,wave_id BIGINT NOT NULL REFERENCES ubos_demo.survey_waves(wave_id) ON DELETE RESTRICT,previous_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('planned','fieldwork','processing','quality_review','complete','cancelled')),note TEXT NOT NULL,actor_ref TEXT NOT NULL,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_ubos_wave_period ON ubos_demo.survey_waves(programme_id,reference_period_start,reference_period_end);
CREATE INDEX IF NOT EXISTS ix_ubos_sample_quality ON ubos_demo.sample_units(wave_id,response_status,quality_state);
CREATE INDEX IF NOT EXISTS ix_ubos_aggregate_release ON ubos_demo.aggregate_cells(wave_id,suppression_state,area_code);